// Fixed vectors from research/40-protocol/PROTOCOL.md, generated by the Java
// harness (FVSign.java + VectorHarness.java) and reproduced by the Python
// reference. They are copied as data; no Java code is vendored here.
const vectorSecret = "84:C1:12:45:0B:68:F9:B2:06:95:00:44:74:37:55:71:60:B5:98:31"

const vectorLoginBody = "_site=ajs&_v=4.11.10.0&cmd=ClientApiLogin%2FLogin" +
	"&password=p%40ss&trigger=login&username=test%40example.com"

func TestSignVectors(t *testing.T) {
	cases := []struct {
		body      string
		timestamp string
		dualHash  string
		signature string
	}{
		{"", "1761177600000", "decaadfebebaefbe", "cbfde26ee626242c"},
		{"abc", "1761177600000", "bf7ff86122acbd24", "881953a05577bb2a"},
		{vectorLoginBody, "1761177600000", "27b77ba0004e206d", "80c6a846fc6a00f3"},
		{"中文&ünïcode", "1761177600123", "3d7e935e13359844", "cfac37be29335bb4"},
	}
	for _, tc := range cases {
		if got := DualHashHex([]byte(tc.body)); got != tc.dualHash {
			t.Errorf("dualHash(%q) = %s, want %s", tc.body, got, tc.dualHash)
		}
		if got := Sign(vectorSecret, tc.body, tc.timestamp); got != tc.signature {
			t.Errorf("sign(%q, %s) = %s, want %s", tc.body, tc.timestamp, got, tc.signature)
		}
	}
	if DefaultSecret != vectorSecret {
		t.Fatalf("DefaultSecret = %q, want the vector secret", DefaultSecret)
	}
}

func TestDualHash(t *testing.T) {
	// Independent vectors: the empty input is the two seed values interleaved;
	// "hello world" comes from the Python reference implementation.
	cases := map[string]string{
		"":            "decaadfebebaefbe",
		"abc":         "bf7ff86122acbd24",
		"hello world": "1e2c08461c340786",
	}
	for input, want := range cases {
		if got := hex.EncodeToString(dualHashBytes(input)); got != want {
			t.Errorf("DualHash(%q) = %s, want %s", input, got, want)
		}
	}
	if DualHash([]byte("a")) == DualHash([]byte("b")) {
		t.Fatal("DualHash collided on one-byte inputs")
	}
}

func dualHashBytes(s string) []byte {
	sum := DualHash([]byte(s))
	return sum[:]
}

func TestBuildQueryVectors(t *testing.T) {
	cases := []struct {
		params map[string]string
		want   string
	}{
		{
			map[string]string{"b": "2", "a": "1", "c": "a b&c=d/é"},
			"a=1&b=2&c=a%20b%26c%3dd%2f%c3%a9",
		},
		{
			map[string]string{"_os_dim": "w=1080&h=2400&d=440", "_site": "ajs"},
			"_os_dim=w%3d1080%26h%3d2400%26d%3d440&_site=ajs",
		},
		{
			map[string]string{"z": "", "A": "~-._"},
			"A=~-._&z=",
		},
	}
	for _, tc := range cases {
		if got := BuildQuery(tc.params); got != tc.want {
			t.Errorf("BuildQuery(%v) = %q, want %q", tc.params, got, tc.want)
		}
	}
}

func TestUIDFormat(t *testing.T) {
	now := time.Unix(1761177600, 123000000)
	uid := NewUID(now, 0xdeadbeef)
	if len(uid) != 22 {
		t.Fatalf("uid %q has length %d, want 22", uid, len(uid))
	}
	base, checksum := uid[:18], uid[18:]
	if got := DualHashHex([]byte(base))[:4]; got != checksum {
		t.Errorf("uid checksum = %s, want %s", checksum, got)
	}
	if base[:8] != "68f97000" {
		t.Errorf("uid seconds prefix = %s, want 68f97000", base[:8])
	}
	if base[8:10] != "7b" {
		t.Errorf("uid low-byte component = %s, want 7b", base[8:10])
	}
	if base[10:] != "deadbeef" {
		t.Errorf("uid random component = %s, want deadbeef", base[10:])
	}
}

func TestLoginSignsRequest(t *testing.T) {
	var sawRequest bool
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		sawRequest = true
		if r.URL.Path != "/client.php" {
			t.Errorf("path = %q, want /client.php", r.URL.Path)
		}
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Errorf("read body: %v", err)
		}
		ts := r.Header.Get("X-Timestamp")
		if ts == "" {
			t.Error("missing X-Timestamp")
		}
		if _, err := strconv.ParseInt(ts, 10, 64); err != nil {
			t.Errorf("X-Timestamp %q is not an integer: %v", ts, err)
		}
		if got, want := r.Header.Get("X-Sig"), Sign(DefaultSecret, string(body), ts); got != want {
			t.Errorf("X-Sig = %s, want %s", got, want)
		}
		values, err := url.ParseQuery(string(body))
		if err != nil {
			t.Errorf("body is not a query string: %v", err)
		}
		for key, want := range map[string]string{
			"cmd":      "ClientApiLogin/Login",
			"username": "test@example.com",
			"password": "p@ss",
			"trigger":  "login",
			"_site":    "ajs",
		} {
			if got := values.Get(key); got != want {
				t.Errorf("body[%s] = %q, want %q", key, got, want)
			}
		}
		_ = json.NewEncoder(w).Encode(map[string]any{
			"Login": map[string]any{
				"AuthResult":      "OK",
				"LoginToken":      "token|suffix",
				"UserName":        "u1",
				"ConnectPassword": "cp",
			},
		})
	}))
	defer srv.Close()

	device := DefaultDevice()
	if err := device.EnsureIDs(); err != nil {
		t.Fatalf("EnsureIDs: %v", err)
	}
	client := NewClient([]string{srv.URL}, device)
	client.HTTP = srv.Client()
	login, err := client.Login(context.Background(), "test@example.com", "p@ss")
	if err != nil {
		t.Fatalf("Login: %v", err)
	}
	if !sawRequest {
		t.Fatal("server never saw a request")
	}
	if !login.OK() {
		t.Fatalf("login not OK: %+v", login)
	}
	if client.LoginToken != "token|suffix" || client.UserName != "u1" || client.ConnectPassword != "cp" {
		t.Fatalf("session not stored: %+v", client)
	}
}
